324	// Sync performs a full synchronization cycle:
325	// Attempts Push; if an HTTP 409 conflict occurs, it reconciles the divergent trees,
326	// writes local conflict files if necessary, and pushes the merged commit.
327	func (e *Engine) Sync(ctx context.Context, author vault.CommitAuthor, message string) (*SyncResult, error) {
328		pushRes, err := e.Push(ctx, author, message)
329		if err == nil {
330			return &SyncResult{
331				CommitHash: pushRes.CommitHash,
332			}, nil
333		}
334	
335		var conflictErr *HeadConflictError
336		if !errors.As(err, &conflictErr) {
337			return nil, err
338		}
339	
340		remoteHead := conflictErr.CurrentHead
341	
342		for attempt := 0; attempt < DefaultMaxSyncRetries; attempt++ {
343			if attempt > 0 {
344				backoff := time.Duration(10*(1<<attempt)) * time.Millisecond
345				select {
346				case <-time.After(backoff):
347				case <-ctx.Done():
348					return nil, ctx.Err()
349				}
350			}
351	
352			// 409 Conflict encountered: Fetch remote state
353			remoteCommitBlob, err := e.Client.GetBlob(ctx, e.VaultID, remoteHead)
354			if err != nil {
355				return nil, fmt.Errorf("sync: failed to fetch remote conflict head %s: %w", remoteHead, err)
356			}
357	
358			remoteCommitBytes, err := vault.DecryptPayload(remoteCommitBlob, e.VaultKey)
359			if err != nil {
360				return nil, fmt.Errorf("sync: failed to decrypt remote commit: %w", err)
361			}
362	
363			remoteCommit, err := vault.ParseCommit(remoteCommitBytes)
364			if err != nil {
365				return nil, fmt.Errorf("sync: failed to parse remote commit: %w", err)
366			}
367	
368			remoteTreeBlob, err := e.Client.GetBlob(ctx, e.VaultID, remoteCommit.TreeHash)
369			if err != nil {
370				return nil, fmt.Errorf("sync: failed to fetch remote tree: %w", err)
371			}
372	
373			remoteTreeBytes, err := vault.DecryptPayload(remoteTreeBlob, e.VaultKey)
374			if err != nil {
375				return nil, fmt.Errorf("sync: failed to decrypt remote tree: %w", err)
376			}
377	
378			remoteTree, err := vault.ParseTree(remoteTreeBytes)
379			if err != nil {
380				return nil, fmt.Errorf("sync: failed to parse remote tree: %w", err)
381			}
382			if err := validateTreePaths(remoteTree); err != nil {
383				return nil, fmt.Errorf("sync: refusing to reconcile with remote commit %s: %w", remoteHead, err)
384			}
385	
386			// Construct current local tree from files on disk
387			localFiles, err := e.ScanBundle()
388			if err != nil {
389				return nil, err
390			}
391	
392			localTree := vault.NewTree()
393			blobsToUpload := make(map[string][]byte)
394			var candidateHashes []string
395	
396			for path, content := range localFiles {
397				plainHash := vault.HashPlaintext(content)
398				envelopeBytes, err := vault.EncryptPayload(content, e.VaultKey)
399				if err != nil {
400					return nil, err
401				}
402				blobHash := vault.HashBlob(envelopeBytes)
403				blobsToUpload[blobHash] = envelopeBytes
404				candidateHashes = append(candidateHashes, blobHash)
405	
406				localTree.Entries[path] = vault.TreeEntry{
407					BlobHash:      blobHash,
408					Size:          int64(len(content)),
409					PlaintextHash: plainHash,
410					ModifiedAt:    time.Now().UTC().Format(time.RFC3339),
411				}
412			}
413	
414			// Reconcile base, local, and remote
415			reconcileRes, err := Reconcile(e.cachedTree, localTree, remoteTree)
416			if err != nil {
417				return nil, fmt.Errorf("sync: reconciliation failed: %w", err)
418			}
419	
420			// Auto-merge bookkeeping files: append-only log.md and per-listing index.md
421			var unresolvedConflicts []Conflict
422			for _, c := range reconcileRes.Conflicts {
423				if c.LocalEntry.BlobHash != "" && c.RemoteEntry.BlobHash != "" {
424					if mergedPlain, ok := e.mergeBookkeeping(ctx, c, localFiles[c.Path]); ok {
425						mergedEnv, err := vault.EncryptPayload(mergedPlain, e.VaultKey)
426						if err == nil {
427							mergedBlobHash := vault.HashBlob(mergedEnv)
428							blobsToUpload[mergedBlobHash] = mergedEnv
429							candidateHashes = append(candidateHashes, mergedBlobHash)
430							localFiles[c.Path] = mergedPlain
431	
432							reconcileRes.MergedTree.Entries[c.Path] = vault.TreeEntry{
433								BlobHash:      mergedBlobHash,
434								Size:          int64(len(mergedPlain)),
435								PlaintextHash: vault.HashPlaintext(mergedPlain),
436								ModifiedAt:    time.Now().UTC().Format(time.RFC3339),
437							}
438							continue
439						}
440					}
441				}
442				unresolvedConflicts = append(unresolvedConflicts, c)
443			}
444			reconcileRes.Conflicts = unresolvedConflicts
445	
446			if len(reconcileRes.Conflicts) > 0 {
447				ApplyConflictFailsafe(reconcileRes.MergedTree, reconcileRes.Conflicts)
448			}
449	
450			// Update local files with remote changes and conflict files
451			diff := vault.DiffTrees(localTree, reconcileRes.MergedTree)
452			toFetch := append(diff.Added, diff.Modified...)
453			writeTargets, deleteTargets, err := e.hubTargets(toFetch, diff.Deleted)
454			if err != nil {
455				return nil, fmt.Errorf("sync: refusing to reconcile with remote commit %s: %w", remoteHead, err)
456			}
457			for _, path := range toFetch {
458				entry := reconcileRes.MergedTree.Entries[path]
459				var plainBytes []byte
460				if localData, ok := localFiles[path]; ok && vault.HashPlaintext(localData) == entry.PlaintextHash {
461					plainBytes = localData
462				} else if envelopeData, ok := blobsToUpload[entry.BlobHash]; ok {
463					var err error
464					plainBytes, err = vault.DecryptPayload(envelopeData, e.VaultKey)
465					if err != nil {
466						return nil, fmt.Errorf("sync: failed to decrypt local blob for %s: %w", path, err)
467					}
468				} else {
469					blobBytes, err := e.Client.GetBlob(ctx, e.VaultID, entry.BlobHash)
470					if err != nil {
471						return nil, fmt.Errorf("sync: failed to fetch blob %s for %s: %w", entry.BlobHash, path, err)
472					}
473					plainBytes, err = vault.DecryptPayload(blobBytes, e.VaultKey)
474					if err != nil {
475						return nil, fmt.Errorf("sync: failed to decrypt %s: %w", path, err)
476					}
477				}
478	
479				fullPath := writeTargets[path]
480				_ = os.MkdirAll(filepath.Dir(fullPath), 0o755)
481				_ = os.WriteFile(fullPath, plainBytes, 0o644)
482			}
483	
484			for _, path := range diff.Deleted {
485				_ = os.Remove(deleteTargets[path])
486			}
487	
488			// Upload new blobs
489			if len(candidateHashes) > 0 {
490				missing, err := e.Client.CheckMissingBlobs(ctx, e.VaultID, candidateHashes)
491				if err == nil {
492					for _, h := range missing {
493						if d, ok := blobsToUpload[h]; ok {
494							_ = e.Client.PutBlob(ctx, e.VaultID, h, d)
495						}
496					}
497				}
498			}
499	
500			// Upload merged tree
501			mergedTreeBytes, _ := reconcileRes.MergedTree.Serialize()
502			mergedTreeEnv, _ := vault.EncryptPayload(mergedTreeBytes, e.VaultKey)
503			mergedTreeHash := vault.HashBlob(mergedTreeEnv)
504			_ = e.Client.PutBlob(ctx, e.VaultID, mergedTreeHash, mergedTreeEnv)
505	
506			// Create merge commit pointing to remoteHead
507			mergeCommit := vault.NewCommit(&remoteHead, mergedTreeHash, author, "Reconcile merge: "+message)
508			mergeCommitBytes, _ := mergeCommit.Serialize()
509			mergeCommitEnv, _ := vault.EncryptPayload(mergeCommitBytes, e.VaultKey)
510			mergeCommitHash := vault.HashBlob(mergeCommitEnv)
511			_ = e.Client.PutBlob(ctx, e.VaultID, mergeCommitHash, mergeCommitEnv)
512	
513			resp, err := e.Client.Commit(ctx, e.VaultID, mergeCommitHash, &remoteHead)
514			if err != nil {
515				var raceErr *HeadConflictError
516				if errors.As(err, &raceErr) {
517					// Server head advanced during reconciliation, retry with new head
518					remoteHead = raceErr.CurrentHead
519					e.cachedTree = remoteTree
520					continue
521				}
522				return nil, fmt.Errorf("sync: failed to commit merged head: %w", err)
523			}
524	
525			e.cachedHead = resp.Head
526			e.cachedTree = reconcileRes.MergedTree
527	
528			if err := e.saveState(); err != nil {
529				return nil, fmt.Errorf("sync: merged commit %s was accepted by the hub, but persisting the sync state failed: %w", resp.Head, err)
530			}
531	
532			return &SyncResult{
533				CommitHash: resp.Head,
534				Conflicts:  reconcileRes.Conflicts,
535			}, nil
536		}
537	
538		return nil, fmt.Errorf("sync: exceeded maximum reconciliation retries (%d)", DefaultMaxSyncRetries)
539	}
