    11	// MergeLogContent performs a 3-way/2-way semantic union of two OKF log.md files.
    12	// It groups change entries by their "## YYYY-MM-DD" date headings, preserves descending
    13	// chronological order, deduplicates identical bullet entries, and maintains any preamble.
    14	func MergeLogContent(localBytes, remoteBytes []byte) ([]byte, error) {
    15		if len(localBytes) == 0 {
    16			return remoteBytes, nil
    17		}
    18		if len(remoteBytes) == 0 {
    19			return localBytes, nil
    20		}
    21		if bytes.Equal(localBytes, remoteBytes) {
    22			return localBytes, nil
    23		}
    24	
    25		localPreamble, localSections := parseLogSections(localBytes)
    26		remotePreamble, remoteSections := parseLogSections(remoteBytes)
    27	
    28		preamble := localPreamble
    29		if strings.TrimSpace(preamble) == "" {
    30			preamble = remotePreamble
    31		}
    32		if strings.TrimSpace(preamble) == "" {
    33			preamble = "# Knowledge Log\n"
    34		}
    35	
    36		// Collect unique dates
    37		dateMap := make(map[string][]string)
    38		for d, entries := range localSections {
    39			dateMap[d] = append(dateMap[d], entries...)
    40		}
    41		for d, entries := range remoteSections {
    42			dateMap[d] = append(dateMap[d], entries...)
    43		}
    44	
    45		var dates []string
    46		for d := range dateMap {
    47			dates = append(dates, d)
    48		}
    49		// Sort descending (latest dates first)
    50		sort.Slice(dates, func(i, j int) bool {
    51			return dates[i] > dates[j]
    52		})
    53	
    54		var sb strings.Builder
    55		sb.WriteString(strings.TrimRight(preamble, "\r\n"))
    56		sb.WriteString("\n\n")
    57	
    58		for i, d := range dates {
    59			rawEntries := dateMap[d]
    60			// Deduplicate entries while preserving first-seen order
    61			seen := make(map[string]struct{})
    62			var uniqueEntries []string
    63			for _, e := range rawEntries {
    64				trimmed := strings.TrimSpace(e)
    65				if trimmed == "" {
    66					continue
    67				}
    68				if _, ok := seen[trimmed]; !ok {
    69					seen[trimmed] = struct{}{}
    70					uniqueEntries = append(uniqueEntries, trimmed)
    71				}
    72			}
    73	
    74			fmt.Fprintf(&sb, "## %s\n", d)
    75			for _, e := range uniqueEntries {
    76				fmt.Fprintf(&sb, "%s\n", e)
